import itertools
data = cells('Allowed assignments', 'L812:N820')
# Filter out Dune
rows = [r for r in data if r[1] != 'Dune']
tasks = sorted(list(set(r[0] for r in rows)))
workers = sorted(list(set(r[1] for r in rows)))
cost_map = {(r[0], r[1]): r[2] for r in rows}
min_cost = float('inf')
for p in itertools.permutations(workers, len(tasks)):
    valid = True
    c = 0
    for t, w in zip(tasks, p):
        if (t, w) not in cost_map:
            valid = False
            break
        c += cost_map[(t, w)]
    if valid:
        if c < min_cost:
            min_cost = c
result = min_cost

