sheet = 'Transition probabilities'
rows = data_rows(sheet, {'G': 'number', 'H': 'string', 'I': 'string'})
trans = {}
for r in rows:
    p = num(sheet, f'G{r}')
    f = str(cell(sheet, f'H{r}'))
    t = str(cell(sheet, f'I{r}'))
    trans[(f, t)] = p

states = ['Active', 'Idle', 'Done']
# step 0: Idle = 1, others = 0
dist = {'Active': 0.0, 'Idle': 1.0, 'Done': 0.0}

for step in range(2):
    new_dist = {s: 0.0 for s in states}
    for s in states:
        for t in states:
            p = trans.get((s, t), 0.0)
            new_dist[t] += dist[s] * p
    dist = new_dist

result = round(dist['Done'], 6)

